const seed=structuredClone(window.DAYLIGHT_SEED);
const STORE='daylight-mobile-state-v1';
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;
let state=load();let selectedDate=new Date();selectedDate.setHours(0,0,0,0);let displayMonth=new Date(selectedDate.getFullYear(),selectedDate.getMonth(),1);let enabled=new Set([...state.people.map(p=>p.id),'parents','school']);let agendaDays=7;let socket=null;let reconnectTimer=null;let toastTimer=null;let pendingScheduleImport=null;let scheduleImportImages=[];let liveDeviceLocations={};let locationWatchId=null;let lastLocationSentAt=0;

function load(){try{const saved=JSON.parse(localStorage.getItem(STORE));if(!saved?.profile?.setupComplete)return mergeSeed({mobilePreferences:saved?.mobilePreferences||{}});return mergeSeed(saved);}catch{return mergeSeed({});}}
function mergeSeed(saved){return {...seed,...saved,people:saved.people||seed.people,preferences:{...seed.preferences,...(saved.preferences||{}),mobileTheme:saved.preferences?.mobileTheme||'dark'},mobilePreferences:{theme:'dark',accent:'#89a9ff',glassMode:'balanced',background:'aurora',largeText:false,reduceMotion:false,locationSharing:false,aliases:{},...(saved.mobilePreferences||{}),aliases:{...(saved.mobilePreferences?.aliases||{})}},routeSettings:{...seed.routeSettings,...(saved.routeSettings||{})},syncSettings:{endpoint:saved.syncSettings?.endpoint||'wss://daylight-sync-relay.onrender.com',pairingCode:saved.syncSettings?.pairingCode||'',deviceId:saved.syncSettings?.deviceId||`mobile-${uid().slice(0,8)}`},bellSchedules:saved.bellSchedules||seed.bellSchedules,specialBellSchedules:saved.specialBellSchedules||seed.specialBellSchedules,customEvents:saved.customEvents||[],syncedCalendarEvents:saved.syncedCalendarEvents||[],todoItems:saved.todoItems||[],groceryItems:saved.groceryItems||[],medications:saved.medications||[],importedSchedules:saved.importedSchedules||[],notificationHistory:saved.notificationHistory||[]};}
function save(sync=true){localStorage.setItem(STORE,JSON.stringify(state));if(sync)sendSnapshot();}
function person(id){return state.people.find(p=>p.id===id)||{id:'parents',name:state.preferences.parentCalendarName||'Parents',subtitle:'Family plans',color:'#f0b84f'};}
function displayName(value){const p=typeof value==='string'?person(value):value;return state.mobilePreferences?.aliases?.[p.id]?.trim()||p.name;}
function ensureProfile(){state.profile={setupComplete:false,familyId:'',familyName:'',memberId:'',memberName:'',role:'guardian',createdAt:'',...(state.profile||{})};}
function showOnboardingIfNeeded(){const visible=!state.profile.setupComplete,screen=document.querySelector('#onboarding');screen.hidden=!visible;document.body.classList.toggle('onboarding-active',visible)}
function finishOnboarding(){save(false);showOnboardingIfNeeded();renderAll();connectSync();updateWeather()}
function fmtTime(value){if(!value)return'';const [h,m]=value.split(':').map(Number);return new Date(2000,0,1,h,m).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}
function mins(value){const [h,m]=value.split(':').map(Number);return h*60+m;}
function daySchedule(owner,date){const key=iso(date),special=state.specialBellSchedules?.[owner]?.[key];if(special)return{...special,special:true};const rows=state.bellSchedules?.[owner]?.[date.getDay()]||[];return{name:rows.length?'Regular schedule':'No school',rows,special:false};}
function override(owner,date){const key=iso(date);return(state.scheduleOverrides||[]).find(item=>item.owner===owner&&key>=item.from&&key<=item.to&&(!item.weekdays||item.weekdays.includes(date.getDay())));}
function scheduleStatus(rows,date){if(!rows.length)return{label:'Nothing scheduled',detail:'A little breathing room.',mode:'empty'};const now=new Date(),same=iso(now)===iso(date),current=now.getHours()*60+now.getMinutes();if(!same||current<mins(rows[0][1]))return{label:'Before school',detail:`Starts ${fmtTime(rows[0][1])}`,mode:'before'};for(let i=0;i<rows.length;i++){const row=rows[i];if(current>=mins(row[1])&&current<mins(row[2]))return{label:row[0],detail:`Ends ${fmtTime(row[2])}`,mode:'now'};const next=rows[i+1];if(next&&current>=mins(row[2])&&current<mins(next[1]))return{label:'Passing period',detail:`${next[0]} at ${fmtTime(next[1])}`,mode:'passing'};}return{label:'School day finished',detail:`Ended ${fmtTime(rows.at(-1)[2])}`,mode:'complete'};}
function calendarEvents(date){const key=iso(date),special=state.people.flatMap(p=>{const schedule=state.specialBellSchedules?.[p.id]?.[key];return schedule?[{id:`special-${p.id}-${key}`,title:schedule.name,date:key,owner:p.id,time:schedule.rows?.[0]?.[1],source:'Special schedule'}]:[];});return[...(state.customEvents||[]).filter(e=>e.date===key),...(state.syncedCalendarEvents||[]).filter(e=>e.date===key),...special].filter(e=>enabled.has(e.owner||'parents'));}
function allEvents(){return[...(state.customEvents||[]),...(state.syncedCalendarEvents||[]),...state.people.flatMap(p=>Object.entries(state.specialBellSchedules?.[p.id]||{}).map(([date,s])=>({id:`special-${p.id}-${date}`,title:s.name,date,owner:p.id,time:s.rows?.[0]?.[1],source:'Special schedule'})))];}
function greeting(){const h=new Date().getHours();return h<5?'Good night.':h<12?'Good morning.':h<17?'Good afternoon.':h<22?'Good evening.':'Good night.';}
function renderHeader(){const now=new Date();document.querySelector('#greeting').textContent=greeting();document.querySelector('#dateLine').textContent=`${now.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'})} · ${now.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}`;}
function renderDates(){const start=new Date(selectedDate);start.setDate(start.getDate()-3);document.querySelector('#dateStrip').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return`<button data-date="${iso(d)}" class="${iso(d)===iso(selectedDate)?'active':''}"><span>${d.toLocaleDateString([],{weekday:'short'}).toUpperCase()}</span><strong>${d.getDate()}</strong></button>`}).join('');}
function renderStudents(){document.querySelector('#studentCards').innerHTML=state.people.map(p=>{const shown=displayName(p),schedule=daySchedule(p.id,selectedDate),rows=schedule.rows,status=scheduleStatus(rows,selectedDate),ov=override(p.id,selectedDate),arrival=ov?.arrival||rows[0]?.[1],leave=arrival?minsToTime(mins(arrival)-15):'',pickup=ov?.pickup||rows.at(-1)?.[2]||'';return`<article class="student-card glass" style="--student:${p.color}" data-student="${p.id}"><header class="student-head"><span class="avatar">${shown.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><strong>${esc(shown)}</strong><small>${esc(p.subtitle.replaceAll('Â·','·'))}</small></div><button class="chevron" aria-label="Show full schedule">⌄</button></header><div class="student-summary"><div class="status-pill"><span>LEAVE BY</span><strong>${leave?fmtTime(leave):'—'}</strong></div><div class="status-pill pickup"><span>PICKUP${ov?.pickupEnd?' WINDOW':''}</span><strong>${pickup?fmtTime(pickup):'—'}${ov?.pickupEnd?`–${fmtTime(ov.pickupEnd)}`:''}</strong></div></div><div class="current-line"><strong>${esc(status.label)}</strong><small>${esc(status.detail)}</small></div><div class="schedule-list"><small>${schedule.special?'SPECIAL SCHEDULE':'REGULAR SCHEDULE'} · ${esc(schedule.name.replaceAll('Â·','·'))}</small>${rows.length?rows.map(r=>`<div class="schedule-row ${status.label===r[0]?'now':''}"><time>${fmtTime(r[1])}<br>${fmtTime(r[2])}</time><i></i><div><strong>${esc(r[0])}</strong><small>${schedule.special?'Special bell schedule':esc(p.subtitle.split('·')[0])}</small></div></div>`).join(''):`<div class="empty">Nothing scheduled.<br>A little breathing room.</div>`}</div></article>`}).join('');}
function minsToTime(total){total=(total+1440)%1440;return`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function eventHtml(e){const p=person(e.owner||'parents');return`<article class="event-item"><i class="event-color" style="background:${p.color}"></i><div><strong>${e.medical?'✚ ':''}${esc(e.title)}</strong><small>${esc(displayName(p))}${e.time?` · ${fmtTime(e.time)}`:''}${e.source?` · ${esc(e.source)}`:''}</small></div></article>`;}
function renderTodayEvents(){const events=calendarEvents(selectedDate);document.querySelector('#todayEvents').innerHTML=events.length?events.map(eventHtml).join(''):`<div class="empty">Nothing planned today.<br>School events and family plans will appear here.</div>`;}
function renderCalendar(){document.querySelector('#calendarTitle').textContent=displayMonth.toLocaleDateString([],{month:'long',year:'numeric'});document.querySelector('#calendarFilters').innerHTML=[...state.people,{id:'parents',name:'Parents',color:'#f0b84f'},{id:'school',name:'School',color:'#7d92a5'}].map(p=>`<button class="${enabled.has(p.id)?'active':''}" style="--color:${p.color}" data-filter="${p.id}">${esc(p.name.split(' ')[0])}</button>`).join('');const first=(displayMonth.getDay()+6)%7,days=new Date(displayMonth.getFullYear(),displayMonth.getMonth()+1,0).getDate();let html=''.padStart(0);for(let i=0;i<first;i++)html+='<span></span>';for(let day=1;day<=days;day++){const d=new Date(displayMonth.getFullYear(),displayMonth.getMonth(),day),events=calendarEvents(d);html+=`<button class="calendar-day ${iso(d)===iso(new Date())?'today':''} ${iso(d)===iso(selectedDate)?'selected':''}" data-calendar-date="${iso(d)}"><strong>${day}</strong><span class="event-dots">${events.slice(0,6).map(e=>`<i style="background:${person(e.owner).color}"></i>`).join('')}</span></button>`;}document.querySelector('#calendarGrid').innerHTML=html;renderSelectedDay();}
function renderSelectedDay(){const events=calendarEvents(selectedDate);document.querySelector('#selectedDayPanel').innerHTML=`<div class="section-title compact"><div><small>SELECTED DAY</small><h2>${selectedDate.toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'})}</h2></div><button class="round-add" data-quick="event">+</button></div><div class="event-list">${events.length?events.map(eventHtml).join(''):'<div class="empty">No calendar entries.</div>'}</div>`;}
function renderTasks(){document.querySelector('#taskDate').value=iso(selectedDate);document.querySelectorAll('#todoForm select[name=owner]').forEach(sel=>sel.innerHTML=[...state.people,{id:'parents',name:'Parents'}].map(p=>`<option value="${p.id}">${esc(displayName(p).split(' ')[0])}</option>`).join(''));const date=iso(selectedDate),todos=state.todoItems.filter(i=>i.date===date),groceries=state.groceryItems.filter(i=>!i.archived);document.querySelector('#todoCount').textContent=todos.length;document.querySelector('#todoList').innerHTML=todos.length?todos.map(i=>listItem(i,'todo')).join(''):'<div class="empty">Nothing to do yet.</div>';document.querySelector('#groceryList').innerHTML=groceries.length?groceries.map(i=>listItem(i,'grocery')).join(''):'<div class="empty">Your grocery list is clear.</div>';renderSuggestions();}
function listItem(item,type){return`<article class="check-item ${item.completed?'done':''}"><button class="check-toggle" data-toggle-item="${item.id}" data-type="${type}">${item.completed?'✓':''}</button><div><strong>${esc(item.title)}</strong><small>${type==='grocery'?(item.quantity||'One item'):esc(displayName(person(item.owner||'parents')))}</small></div><button class="delete-button" data-delete-item="${item.id}" data-type="${type}">×</button></article>`;}
function learning(type){try{return JSON.parse(localStorage.getItem(`daylight-${type}-learning`)||'{}')}catch{return{}}}
function learn(type,title){const data=learning(type),key=title.toLowerCase();data[key]={title,count:(data[key]?.count||0)+1};localStorage.setItem(`daylight-${type}-learning`,JSON.stringify(data));}
function renderSuggestions(){const existing=new Set([...state.todoItems,...state.groceryItems].filter(i=>!i.completed&&!i.archived).map(i=>i.title.toLowerCase())),dismissed=new Set(state.suggestionDismissals||[]);const suggestions=['grocery','todo'].flatMap(type=>Object.entries(learning(type)).map(([key,v])=>({...v,key,type}))).filter(i=>i.count>=2&&!existing.has(i.key)&&!dismissed.has(`${i.type}:${i.key}`)).sort((a,b)=>b.count-a.count).slice(0,12);document.querySelector('#suggestionList').innerHTML=suggestions.length?suggestions.map(i=>`<article class="suggestion"><div><strong>${esc(i.title)}</strong><small>${i.type==='grocery'?'Frequently bought':'Frequently added'} · ${i.count} times</small></div><button data-dismiss-suggestion="${i.type}:${esc(i.key)}">−</button><button class="add" data-add-suggestion="${i.type}:${esc(i.key)}">+</button></article>`).join(''):'<div class="empty">Suggestions will appear as Daylight learns your routines.</div>';}
function renderAgenda(){const start=new Date(selectedDate),end=new Date(start);end.setDate(end.getDate()+agendaDays);const events=allEvents().filter(e=>{const d=new Date(`${e.date}T12:00:00`);return d>=start&&d<end&&enabled.has(e.owner||'parents')}).sort((a,b)=>`${a.date}${a.time||''}`.localeCompare(`${b.date}${b.time||''}`));document.querySelector('#agendaList').innerHTML=events.length?events.map(e=>{const d=new Date(`${e.date}T12:00:00`),p=person(e.owner);return`<article class="agenda-item glass"><div class="agenda-date"><span>${d.toLocaleDateString([],{weekday:'short'}).toUpperCase()}</span><strong>${d.getDate()}</strong></div><i class="event-color" style="background:${p.color}"></i><div><strong>${esc(e.title)}</strong><small>${esc(p.name)}${e.time?` · ${fmtTime(e.time)}`:''}</small></div></article>`}).join(''):'<div class="glass panel empty">The family agenda is clear.</div>';}
async function updateWeather(){const target=String(state.preferences.weatherLocation||'').trim();if(!target){state.weatherCache=null;renderWeather();return}try{const place=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(target)}&count=1&language=en&format=json`).then(r=>r.json()).then(x=>x.results?.[0]);if(!place)throw Error();const w=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}&current=temperature_2m,weather_code,is_day&daily=temperature_2m_max,temperature_2m_min,weather_code&temperature_unit=fahrenheit&timezone=auto`).then(r=>r.json());state.weatherCache={temperature:Math.round(w.current.temperature_2m),code:w.current.weather_code,location:place.name,forecast:(w.daily.time||[]).map((date,i)=>({date,high:Math.round(w.daily.temperature_2m_max[i]),low:Math.round(w.daily.temperature_2m_min[i]),code:w.daily.weather_code[i]})),updatedAt:Date.now()};save(false);renderWeather();}catch{renderWeather();}}
function renderWeather(){const w=state.weatherCache;if(!w)return;const icons=w.code>=95?'⛈️':w.code>=71?'❄️':w.code>=51?'🌧️':w.code>=2?'⛅':'☀️';document.querySelector('#weatherNow').textContent=`${w.temperature}°`;document.querySelector('#weatherIcon').textContent=icons;document.querySelector('#weatherAdvice').textContent=w.location;}
function snapshot(){return{customEvents:state.customEvents,syncedCalendarEvents:state.syncedCalendarEvents,todoItems:state.todoItems,groceryItems:state.groceryItems,medications:state.medications,importedSchedules:state.importedSchedules||[],customPortals:state.customPortals||[],syncTombstones:state.syncTombstones||[],scheduleOverrides:(state.scheduleOverrides||[]).filter(x=>x.userException),people:state.people,bellSchedules:state.bellSchedules,specialBellSchedules:state.specialBellSchedules,routeSettings:{...state.routeSettings,deviceLocations:liveDeviceLocations},preferences:{familyName:state.preferences.familyName,parentCalendarName:state.preferences.parentCalendarName,weatherLocation:state.preferences.weatherLocation},updatedAt:new Date().toISOString()};}
function renderPortals(){const container=document.querySelector('#mobilePortals');if(!container)return;const portals=(state.customPortals||[]).filter(portal=>portal.url);container.innerHTML=portals.length?portals.map(portal=>`<a href="${esc(portal.url)}" target="_blank" rel="noopener">${esc(portal.name||portal.title||'Family portal')}</a>`).join(''):'<span>No portals connected yet</span>';}
function ensureIdentity(){if(!state.syncSettings.deviceId)state.syncSettings.deviceId=`mobile-${uid().slice(0,8)}`;save(false);}
const utf8=new TextEncoder(),utf8Decoder=new TextDecoder();
function bytesToBase64(bytes){let value='';bytes.forEach(byte=>value+=String.fromCharCode(byte));return btoa(value)}
function base64ToBytes(value){return Uint8Array.from(atob(value),char=>char.charCodeAt(0))}
async function syncRoomId(){const digest=await crypto.subtle.digest('SHA-256',utf8.encode(`daylight-room:${state.syncSettings.pairingCode.trim().toUpperCase()}`));return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('')}
async function syncCryptoKey(){const material=await crypto.subtle.importKey('raw',utf8.encode(state.syncSettings.pairingCode.trim().toUpperCase()),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:utf8.encode('daylight-family-sync-v1'),iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptSyncPayload(payload){const iv=crypto.getRandomValues(new Uint8Array(12)),key=await syncCryptoKey(),data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,utf8.encode(JSON.stringify(payload)));return{iv:bytesToBase64(iv),data:bytesToBase64(new Uint8Array(data))}}
async function decryptSyncPayload(encrypted){const key=await syncCryptoKey(),data=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(encrypted.iv)},key,base64ToBytes(encrypted.data)),payload=JSON.parse(utf8Decoder.decode(data));if(payload.routeSettings?.deviceLocations){liveDeviceLocations={...liveDeviceLocations,...payload.routeSettings.deviceLocations};payload.routeSettings={...payload.routeSettings};delete payload.routeSettings.deviceLocations;queueMicrotask(refreshMobileLiveMap)}return payload}
function mergeSyncRecords(local=[],incoming=[]){const merged=new Map();[...local,...incoming].forEach(item=>{const key=item.id||`${item.owner||'parents'}|${item.date||''}|${item.time||''}|${item.title||''}`;merged.set(key,{...(merged.get(key)||{}),...item})});return[...merged.values()]}
function rememberDeletion(collection,id){state.syncTombstones=mergeSyncRecords(state.syncTombstones||[],[{id:`${collection}:${id}`,collection,recordId:id,deletedAt:new Date().toISOString()}]);}
function applyTombstones(){for(const tombstone of state.syncTombstones||[]){if(Array.isArray(state[tombstone.collection]))state[tombstone.collection]=state[tombstone.collection].filter(item=>item.id!==tombstone.recordId);}}
function connectSync(){clearTimeout(reconnectTimer);try{socket?.close()}catch{}socket=null;const c=state.syncSettings;if(!c.endpoint||!c.pairingCode){setSync('offline');return}if(!/^wss:\/\//i.test(c.endpoint)){setSync('error');return}setSync('connecting');try{socket=new WebSocket(c.endpoint);socket.onopen=async()=>{setSync('online');socket.send(JSON.stringify({type:'hello',roomId:await syncRoomId(),deviceId:c.deviceId,client:'daylight-mobile'}));setTimeout(sendSnapshot,600)};socket.onmessage=async e=>{try{const m=JSON.parse(e.data);if(m.type==='sync-request'){sendSnapshot();return}if(m.type!=='snapshot'||m.deviceId===c.deviceId||!m.encrypted)return;applySnapshot(await decryptSyncPayload(m.encrypted))}catch{setSync('error');toast('Desktop sync update failed')}};socket.onclose=()=>{setSync('offline');reconnectTimer=setTimeout(connectSync,2000)};socket.onerror=()=>setSync('error')}catch{setSync('error')}}
function applySnapshot(data){const changed=[];['customEvents','syncedCalendarEvents','todoItems','groceryItems','medications','people'].forEach(k=>{if(Array.isArray(data[k])){const merged=mergeSyncRecords(state[k]||[],data[k]);if(JSON.stringify(state[k])!==JSON.stringify(merged)){state[k]=merged;changed.push(k)}}});['bellSchedules','specialBellSchedules','routeSettings'].forEach(k=>{if(data[k]&&typeof data[k]==='object'&&JSON.stringify(state[k])!==JSON.stringify(data[k])){state[k]=data[k];changed.push(k)}});if(Array.isArray(data.scheduleOverrides)){const next=mergeSyncRecords((state.scheduleOverrides||[]).filter(x=>x.userException),data.scheduleOverrides);if(JSON.stringify(state.scheduleOverrides)!==JSON.stringify(next)){state.scheduleOverrides=next;changed.push('scheduleOverrides')}}if(data.preferences){const current=Object.fromEntries(Object.keys(data.preferences).map(k=>[k,state.preferences[k]]));if(JSON.stringify(current)!==JSON.stringify(data.preferences)){state.preferences={...state.preferences,...data.preferences};changed.push('preferences')}}save(false);if(!changed.length)return;renderHeader();const active=document.querySelector('.view.active')?.dataset.view;if(active==='today'&&changed.some(k=>['customEvents','syncedCalendarEvents','people','bellSchedules','specialBellSchedules','scheduleOverrides'].includes(k))){renderStudents();renderTodayEvents()}else if(active==='calendar'&&changed.some(k=>['customEvents','syncedCalendarEvents','people','scheduleOverrides'].includes(k)))renderCalendar();else if(active==='tasks'&&changed.some(k=>['todoItems','groceryItems','people'].includes(k)))renderTasks();else if(active==='agenda'&&changed.some(k=>['customEvents','syncedCalendarEvents','people','scheduleOverrides'].includes(k)))renderAgenda();document.querySelector('#noticeCount').hidden=!renderNotices().length;document.querySelector('#noticeCount').textContent=Math.min(9,renderNotices().length)}
const applySnapshotRecords=applySnapshot;
applySnapshot=function(data){if(Array.isArray(data.syncTombstones))state.syncTombstones=mergeSyncRecords(state.syncTombstones||[],data.syncTombstones);for(const tombstone of state.syncTombstones||[]){if(Array.isArray(data[tombstone.collection]))data[tombstone.collection]=data[tombstone.collection].filter(item=>item.id!==tombstone.recordId);}applyTombstones();return applySnapshotRecords(data);};
async function sendSnapshot(){if(socket?.readyState!==WebSocket.OPEN)return;socket.send(JSON.stringify({type:'snapshot',roomId:await syncRoomId(),deviceId:state.syncSettings.deviceId,encrypted:await encryptSyncPayload(snapshot())}))}
function refreshMobileLiveMap(){const wrap=document.querySelector('#mobileLiveMapWrap');if(wrap)wrap.innerHTML=mobileRouteMapHtml()}
function stopLocationSharing(broadcast=true){if(locationWatchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(locationWatchId);locationWatchId=null;delete liveDeviceLocations[state.syncSettings.deviceId];if(broadcast)sendSnapshot();refreshMobileLiveMap()}
function startLocationSharing(){if(!state.mobilePreferences.locationSharing)return;if(!navigator.geolocation){state.mobilePreferences.locationSharing=false;save(false);toast('Location is not available on this device');return}if(locationWatchId!==null)return;locationWatchId=navigator.geolocation.watchPosition(position=>{const now=Date.now();liveDeviceLocations[state.syncSettings.deviceId]={lat:Number(position.coords.latitude),lng:Number(position.coords.longitude),accuracy:Math.round(position.coords.accuracy||0),updatedAt:now,name:state.profile.memberName||'Family phone',deviceId:state.syncSettings.deviceId};refreshMobileLiveMap();if(now-lastLocationSentAt>=5000){lastLocationSentAt=now;sendSnapshot()}},error=>{state.mobilePreferences.locationSharing=false;save(false);locationWatchId=null;const toggle=document.querySelector('#locationSharingToggle');if(toggle)toggle.checked=false;toast(error.code===1?'Location permission was not allowed':'Daylight could not update this phone’s location')},{enableHighAccuracy:true,maximumAge:4000,timeout:15000})}
function setSync(status){document.querySelector('#syncDot').className=status==='online'?'online':'';document.querySelector('#syncButton').dataset.status=status;}
function renderNotices(){const upcoming=allEvents().filter(e=>e.date>=iso(new Date())).sort((a,b)=>`${a.date}${a.time||''}`.localeCompare(`${b.date}${b.time||''}`)).slice(0,12),tasks=state.todoItems.filter(i=>!i.completed&&i.date<=iso(new Date())).map(i=>({title:i.title,detail:`To do · ${person(i.owner||'parents').name}`}));return[...tasks,...upcoming.map(e=>({title:e.title,detail:`${new Date(`${e.date}T12:00:00`).toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'})} · ${person(e.owner).name}`}))];}
function openSheet(type){const titles={event:['QUICK ADD','Add an event'],notifications:['DAYLIGHT CENTER','Notifications'],sync:['CONNECTIONS','Desktop sync'],route:['MORNING DRIVE','School route'],health:['PRIVATE ON THIS DEVICE','Health & medication'],family:['YOUR HOUSEHOLD','Family'],connections:['SYSTEM STATUS','Connections'],appearance:['PERSONALIZE DAYLIGHT','Appearance']},[eyebrow,title]=titles[type]||['DAYLIGHT','Details'];document.querySelector('#sheetEyebrow').textContent=eyebrow;document.querySelector('#sheetTitle').textContent=title;document.querySelector('#sheetBody').innerHTML=type==='family'?familySheet():sheetContent(type);document.querySelector('#sheetBackdrop').hidden=false;document.querySelector('#sheet').hidden=false;document.body.style.overflow='hidden';}
function familySheet(){return`<div class="family-member-list">${state.people.length?state.people.map(child=>`<article class="connection-card"><strong>${esc(child.name)}</strong><small>${esc(child.school||'School not added')}${child.grade?` · ${esc(child.grade)}`:''}</small><button type="button" data-remove-family-member="${child.id}">Remove</button></article>`).join(''):'<div class="empty">No children added yet.</div>'}</div><form id="familyMemberForm" class="sheet-form"><label>Child's name<input name="name" required placeholder="Full name"></label><label>School<input name="school" placeholder="School name"></label><label>Grade<input name="grade" placeholder="Grade"></label><label>Color<input name="color" type="color" value="#89a9ff"></label><button class="primary">Add child</button></form><div class="appearance-section"><span class="setting-label">IMPORTED BELL SCHEDULES</span>${(state.importedSchedules||[]).length?state.importedSchedules.map(item=>`<article class="connection-card"><strong>${esc(item.name)}</strong><small>${esc(displayName(person(item.ownerId)))} · Added ${new Date(item.createdAt).toLocaleDateString()}</small><button type="button" data-remove-imported-schedule="${item.id}">Delete</button></article>`).join(''):'<div class="empty">No screenshot schedules added.</div>'}</div>`;}
function mobileRouteMapHtml(){const routePoints=[state.routeSettings?.origin?.location,...(state.routeSettings?.stops||[]).map(stop=>stop.location)].filter(point=>Number.isFinite(point?.lat)&&Number.isFinite(point?.lng)),locations=Object.entries(liveDeviceLocations).filter(([,location])=>Date.now()-Number(location.updatedAt||0)<10*60*1000&&Number.isFinite(location.lat)&&Number.isFinite(location.lng));if(!routePoints.length&&!locations.length)return`<div class="mobile-map-empty">Live family locations will appear here after a connected phone shares its position.</div>`;const all=[...routePoints,...locations.map(([,location])=>location)],lats=all.map(point=>point.lat),lngs=all.map(point=>point.lng),minLat=Math.min(...lats)-.006,maxLat=Math.max(...lats)+.006,minLng=Math.min(...lngs)-.006,maxLng=Math.max(...lngs)+.006,dot=(location,label,type)=>{const left=((location.lng-minLng)/(maxLng-minLng))*100,top=(1-(location.lat-minLat)/(maxLat-minLat))*100;return`<span class="mobile-map-dot ${type}" style="left:${left}%;top:${top}%" title="${esc(label)}"><i></i></span>`};return`<div class="mobile-live-map"><iframe title="Live school route map" src="https://www.openstreetmap.org/export/embed.html?bbox=${minLng}%2C${minLat}%2C${maxLng}%2C${maxLat}&amp;layer=mapnik"></iframe>${routePoints.map((point,index)=>dot(point,index?'School':'Start','stop')).join('')}${locations.map(([,location])=>dot(location,location.name||'Family device','live')).join('')}</div><div class="mobile-location-list">${locations.length?locations.map(([,location])=>`<span><i></i><strong>${esc(location.name||'Family device')}</strong><small>Updated ${new Date(location.updatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small></span>`).join(''):'<small>No phone is currently sharing a live location.</small>'}</div>`}
function locationSharingControl(){return`<label class="toggle-row live-location-toggle"><span><strong>Share this phone’s location</strong><small>Visible only to devices connected with your encrypted family code</small></span><input id="locationSharingToggle" type="checkbox" ${state.mobilePreferences.locationSharing?'checked':''}></label><div id="mobileLiveMapWrap">${mobileRouteMapHtml()}</div>`}
function closeSheet(){document.querySelector('#sheetBackdrop').hidden=true;document.querySelector('#sheet').hidden=true;document.body.style.overflow='';}
function sheetContent(type){if(type==='event')return`<form id="eventForm" class="sheet-form"><label>Title<input name="title" required placeholder="Appointment, practice, school event…"></label><label>For<select name="owner">${[...state.people,{id:'parents',name:'Parents'}].map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${iso(selectedDate)}" required></label><label>Time<input name="time" type="time"></label><label class="toggle-row">Important<input name="priority" type="checkbox"></label><label class="toggle-row">Medical appointment<input name="medical" type="checkbox"></label><button class="primary">Add event</button></form>`;if(type==='notifications'){const items=renderNotices();return items.length?items.map(i=>`<article class="notice-item"><strong>${esc(i.title)}</strong><small>${esc(i.detail)}</small></article>`).join(''):'<div class="empty">All caught up.</div>'}if(type==='sync'||type==='connections')return`<div class="connection-card"><strong>Desktop sync · ${socket?.readyState===WebSocket.OPEN?'Connected':'Offline ready'}</strong><small>Changes stay on this phone until a secure relay is available.</small></div><form id="syncForm" class="sheet-form"><label>Secure relay address<input name="endpoint" value="${esc(state.syncSettings.endpoint)}" placeholder="wss://your-daylight-relay.example"></label><label>Pairing code<input name="pairingCode" value="${esc(state.syncSettings.pairingCode)}" placeholder="Same code as desktop"></label><label>This device<input value="${esc(state.syncSettings.deviceId)}" disabled></label><button class="primary">Save and connect</button></form><div class="connection-card"><strong>Weather</strong><small>${state.weatherCache?'Connected through Open-Meteo':'Waiting for network'}</small></div><div class="connection-card"><strong>Offline storage</strong><small>Active · schedules and lists remain available without a connection.</small></div>`;if(type==='route')return`${locationSharingControl()}<div class="connection-card route-intro"><strong>Morning order</strong><small>Verified on desktop · tap Open route to begin navigation.</small></div><div class="route-stop-list">${(state.routeSettings.stops||[]).map((s,i)=>routeStopHtml(s,i)).join('')}</div><button class="primary" id="openRoute">Open route</button>`;if(type==='health')return`<form id="medForm" class="sheet-form"><label>Medication or health note<input name="title" required></label><label>For<select name="owner">${state.people.map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('')}</select></label><label>Instructions<textarea name="instructions"></textarea></label><button class="primary">Save health item</button></form>${(state.medications||[]).map(m=>`<div class="connection-card"><strong>${esc(m.title)}</strong><small>${esc(displayName(person(m.owner)))} · ${esc(m.instructions||'No instructions')}</small></div>`).join('')}`;if(type==='appearance')return appearanceSheet();return'';}
function routeStopHtml(stop,index){const raw=stop.formattedAddress||stop.address||'',parts=raw.split(',').map(part=>part.trim()).filter(Boolean),street=parts[0]||'Address not verified',locality=parts.slice(1,3).join(', ');return`<article class="route-stop"><b>${index+1}</b><div><strong>${esc(displayName(person(stop.id)))}</strong><span>${esc(stop.school||'School')}</span><small><em>${esc(street)}</em>${locality?`<i>${esc(locality)}</i>`:''}</small></div></article>`;}
function appearanceSheet(){const p=state.mobilePreferences;return`<form id="appearanceForm" class="appearance-form"><div class="appearance-section"><span class="setting-label">DISPLAY NAMES · THIS DEVICE ONLY</span>${state.people.map(child=>`<label>${esc(child.name)}<input name="alias-${child.id}" value="${esc(p.aliases?.[child.id]||'')}" placeholder="Display as ${esc(child.name.split(' ')[0])}"></label>`).join('')}</div><div class="appearance-section"><span class="setting-label">THEME</span><label class="toggle-row">Light mode<input id="themeToggle" type="checkbox" ${p.theme==='light'?'checked':''}></label><label>Liquid glass<select id="glassMode"><option value="clear" ${p.glassMode==='clear'?'selected':''}>Clear and airy</option><option value="balanced" ${p.glassMode==='balanced'?'selected':''}>Balanced</option><option value="frosted" ${p.glassMode==='frosted'?'selected':''}>Frosted</option><option value="solid" ${p.glassMode==='solid'?'selected':''}>High readability</option></select></label><label>Background<select id="mobileBackground"><option value="aurora" ${p.background==='aurora'?'selected':''}>Aurora night</option><option value="ocean" ${p.background==='ocean'?'selected':''}>Ocean blue</option><option value="berry" ${p.background==='berry'?'selected':''}>Berry dusk</option><option value="graphite" ${p.background==='graphite'?'selected':''}>Graphite</option></select></label><div class="accent-row">${['#89a9ff','#62d2b3','#ff77bd','#a98cff','#f0b85b'].map(color=>`<button type="button" data-mobile-accent="${color}" class="${p.accent===color?'active':''}" style="--swatch:${color}" aria-label="Use ${color}"></button>`).join('')}</div></div><div class="appearance-section"><span class="setting-label">ACCESSIBILITY</span><label class="toggle-row">Larger text<input id="largeTextToggle" type="checkbox" ${p.largeText?'checked':''}></label><label class="toggle-row">Reduce motion<input id="motionToggle" type="checkbox" ${p.reduceMotion?'checked':''}></label></div><button class="primary">Save on this iPhone</button><small class="local-note">These choices stay on this device and never rename a child in the shared family system.</small></form>`;}
function navigate(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));window.scrollTo({top:0,behavior:state.preferences.reduceMotion?'auto':'smooth'});if(name==='calendar')renderCalendar();if(name==='tasks')renderTasks();if(name==='agenda')renderAgenda();}
function toast(message){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=message;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,2500)}
function applyMobileAppearance(){const p=state.mobilePreferences||{};document.body.classList.toggle('light',p.theme==='light');document.body.classList.toggle('mobile-large-text',Boolean(p.largeText));document.body.classList.toggle('mobile-reduce-motion',Boolean(p.reduceMotion));document.body.dataset.glass=p.glassMode||'balanced';document.body.dataset.background=p.background||'aurora';document.documentElement.style.setProperty('--accent',p.accent||'#89a9ff');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',p.theme==='light'?'#e7eef4':'#08111b');}
function renderAll(){applyMobileAppearance();renderHeader();renderDates();renderStudents();renderTodayEvents();renderCalendar();renderTasks();renderAgenda();renderWeather();renderPortals();const noticeCount=renderNotices().length,badge=document.querySelector('#noticeCount');badge.hidden=!noticeCount;badge.textContent=Math.min(9,noticeCount);}

document.addEventListener('click',e=>{const accent=e.target.closest('[data-mobile-accent]');if(accent){state.mobilePreferences.accent=accent.dataset.mobileAccent;save(false);applyMobileAppearance();document.querySelectorAll('[data-mobile-accent]').forEach(button=>button.classList.toggle('active',button===accent));return}const nav=e.target.closest('[data-nav]');if(nav)navigate(nav.dataset.nav);const go=e.target.closest('[data-go]');if(go)navigate(go.dataset.go);const quick=e.target.closest('[data-quick]');if(quick)openSheet(quick.dataset.quick);const card=e.target.closest('.student-card');if(card&&!e.target.closest('button:not(.chevron)'))card.classList.toggle('open');const date=e.target.closest('[data-date]');if(date){selectedDate=new Date(`${date.dataset.date}T12:00:00`);renderAll()}const cal=e.target.closest('[data-calendar-date]');if(cal){selectedDate=new Date(`${cal.dataset.calendarDate}T12:00:00`);renderCalendar()}const filter=e.target.closest('[data-filter]');if(filter){enabled.has(filter.dataset.filter)?enabled.delete(filter.dataset.filter):enabled.add(filter.dataset.filter);renderCalendar()}const tab=e.target.closest('[data-list-tab]');if(tab){document.querySelectorAll('[data-list-tab]').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('[data-list-panel]').forEach(x=>x.hidden=x.dataset.listPanel!==tab.dataset.listTab)}const days=e.target.closest('[data-days]');if(days){agendaDays=Number(days.dataset.days);document.querySelectorAll('[data-days]').forEach(x=>x.classList.toggle('active',x===days));renderAgenda()}const sheet=e.target.closest('[data-sheet]');if(sheet)openSheet(sheet.dataset.sheet);const toggle=e.target.closest('[data-toggle-item]');if(toggle){const list=toggle.dataset.type==='todo'?state.todoItems:state.groceryItems,item=list.find(i=>i.id===toggle.dataset.toggleItem);if(item)item.completed=!item.completed;save();renderTasks()}const del=e.target.closest('[data-delete-item]');if(del){const key=del.dataset.type==='todo'?'todoItems':'groceryItems';state[key]=state[key].filter(i=>i.id!==del.dataset.deleteItem);save();renderTasks()}const dismiss=e.target.closest('[data-dismiss-suggestion]');if(dismiss){state.suggestionDismissals=[...(state.suggestionDismissals||[]),dismiss.dataset.dismissSuggestion];save();renderSuggestions()}const add=e.target.closest('[data-add-suggestion]');if(add){const[type,key]=add.dataset.addSuggestion.split(':');const item=learning(type)[key];if(item){if(type==='todo')state.todoItems.push({id:uid(),title:item.title,date:iso(selectedDate),owner:'parents',completed:false});else state.groceryItems.push({id:uid(),title:item.title,quantity:'',completed:false});save();renderTasks()}}});
document.querySelector('#closeSheet').onclick=closeSheet;document.querySelector('#sheetBackdrop').onclick=closeSheet;document.querySelector('#notifyButton').onclick=()=>openSheet('notifications');document.querySelector('#syncButton').onclick=()=>openSheet('sync');document.querySelector('#prevMonth').onclick=()=>{displayMonth=new Date(displayMonth.getFullYear(),displayMonth.getMonth()-1,1);renderCalendar()};document.querySelector('#nextMonth').onclick=()=>{displayMonth=new Date(displayMonth.getFullYear(),displayMonth.getMonth()+1,1);renderCalendar()};document.querySelector('#taskDate').onchange=e=>{selectedDate=new Date(`${e.target.value}T12:00:00`);renderTasks()};
document.querySelector('#previousHeaderDay').onclick=()=>{selectedDate.setDate(selectedDate.getDate()-1);renderAll()};document.querySelector('#nextHeaderDay').onclick=()=>{selectedDate.setDate(selectedDate.getDate()+1);renderAll()};
document.addEventListener('click',event=>{const target=event.target.closest('[data-delete-item]');if(target)rememberDeletion(target.dataset.type==='todo'?'todoItems':'groceryItems',target.dataset.deleteItem);},true);
document.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-family-member]');if(!remove)return;const id=remove.dataset.removeFamilyMember,child=state.people.find(person=>person.id===id);if(!child||!confirm(`Remove ${child.name} from this family?`))return;rememberDeletion('people',id);state.people=state.people.filter(person=>person.id!==id);delete state.bellSchedules[id];delete state.specialBellSchedules[id];state.routeSettings.stops=(state.routeSettings.stops||[]).filter(stop=>stop.personId!==id);save();openSheet('family');renderAll();});
document.addEventListener('submit',event=>{if(event.target.id!=='familyMemberForm')return;event.preventDefault();event.stopImmediatePropagation();const data=new FormData(event.target),id=`person-${uid().slice(0,10)}`,name=String(data.get('name')).trim();state.people.push({id,name,school:String(data.get('school')||'').trim(),grade:String(data.get('grade')||'').trim(),color:String(data.get('color')||'#89a9ff'),initials:name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()});state.bellSchedules[id]={};state.specialBellSchedules[id]={};save();openSheet('family');renderAll();toast(`${name} added`);},true);
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);if(form.id==='appearanceForm'){state.people.forEach(child=>state.mobilePreferences.aliases[child.id]=String(data.get(`alias-${child.id}`)||'').trim());state.mobilePreferences.theme=document.querySelector('#themeToggle').checked?'light':'dark';state.mobilePreferences.largeText=document.querySelector('#largeTextToggle').checked;state.mobilePreferences.reduceMotion=document.querySelector('#motionToggle').checked;state.mobilePreferences.glassMode=document.querySelector('#glassMode').value;state.mobilePreferences.background=document.querySelector('#mobileBackground').value;save(false);closeSheet();renderAll();toast('Appearance saved on this iPhone');return}if(form.id==='eventForm'){state.customEvents.push({id:uid(),title:data.get('title'),owner:data.get('owner'),date:data.get('date'),time:data.get('time'),priority:data.get('priority')==='on',medical:data.get('medical')==='on',source:'Manual'});save();closeSheet();renderAll();toast('Event added')}if(form.id==='todoForm'){const title=data.get('title').trim();state.todoItems.push({id:uid(),title,date:iso(selectedDate),owner:data.get('owner'),completed:false});learn('todo',title);save();form.reset();renderTasks()}if(form.id==='groceryForm'){const title=data.get('title').trim();state.groceryItems.push({id:uid(),title,quantity:data.get('quantity'),completed:false});learn('grocery',title);save();form.reset();renderTasks()}if(form.id==='syncForm'){state.syncSettings.endpoint=data.get('endpoint').trim();state.syncSettings.pairingCode=data.get('pairingCode').trim().toUpperCase();save(false);connectSync();closeSheet();toast('Sync settings saved')}if(form.id==='medForm'){state.medications.push({id:uid(),title:data.get('title'),owner:data.get('owner'),instructions:data.get('instructions')});save();openSheet('health');toast('Health item saved')}if(form.id==='assistantForm'){assistant(data.get('prompt'));form.reset()}});
document.addEventListener('change',e=>{if(e.target.id==='themeToggle'){state.mobilePreferences.theme=e.target.checked?'light':'dark';applyMobileAppearance()}if(e.target.id==='largeTextToggle'){state.mobilePreferences.largeText=e.target.checked;applyMobileAppearance()}if(e.target.id==='motionToggle'){state.mobilePreferences.reduceMotion=e.target.checked;applyMobileAppearance()}if(e.target.id==='glassMode'){state.mobilePreferences.glassMode=e.target.value;applyMobileAppearance()}if(e.target.id==='mobileBackground'){state.mobilePreferences.background=e.target.value;applyMobileAppearance()}if(e.target.id==='locationSharingToggle'){state.mobilePreferences.locationSharing=e.target.checked;save(false);e.target.checked?startLocationSharing():stopLocationSharing();toast(e.target.checked?'Live family location enabled':'Location sharing stopped')}});
function assistant(prompt){const text=String(prompt||'').trim(),reply=document.querySelector('#assistantReply');const add=text.match(/add (.+?)(?: on | )(today|tomorrow|\d{4}-\d{2}-\d{2})(?: at (\d{1,2}(?::\d{2})?\s?(?:am|pm)?))?/i);if(add){const date=new Date();if(add[2].toLowerCase()==='tomorrow')date.setDate(date.getDate()+1);else if(/^\d/.test(add[2]))date.setTime(new Date(`${add[2]}T12:00:00`).getTime());const selectedPerson=state.people.find(person=>text.toLowerCase().includes(person.name.toLowerCase())||text.toLowerCase().includes(person.name.split(' ')[0].toLowerCase())),title=add[1].replace(new RegExp(`\\s+for\\s+${selectedPerson?.name.split(' ')[0]||'parents'}$`,'i'),'');state.customEvents.push({id:uid(),title,owner:selectedPerson?.id||'parents',date:iso(date),time:'',source:'Daylight Assistant'});save();renderAll();reply.textContent=`Added “${title}” to ${iso(date)}.`;return}if(/schedule/i.test(text)){reply.textContent=state.people.map(p=>{const s=daySchedule(p.id,selectedDate);return`${p.name.split(' ')[0]}: ${s.name}, ${s.rows.length} blocks.`}).join(' ');return}reply.textContent=`Today has ${calendarEvents(selectedDate).length} calendar events and ${state.todoItems.filter(i=>i.date===iso(selectedDate)&&!i.completed).length} open tasks. I can also add an event or show the school schedule.`;}
document.addEventListener('click',e=>{if(e.target.id==='openRoute'){const stops=state.routeSettings.stops.filter(s=>s.formattedAddress||s.address).map(s=>encodeURIComponent(s.formattedAddress||s.address));if(stops.length)location.href=`https://www.google.com/maps/dir/?api=1&destination=${stops.at(-1)}&waypoints=${stops.slice(0,-1).join('%7C')}`;else toast('Add and verify school addresses on desktop first')}});
function scheduleRelayUrl(){return String(state.syncSettings.endpoint||'').replace(/^wss:/i,'https:').replace(/^ws:/i,'http:').replace(/\/$/,'')+'/api/parse-schedule'}
function importOwnerOptions(){const select=document.querySelector('#scheduleImportOwner'),label=document.querySelector('#scheduleImportOwnerLabel');select.innerHTML=state.people.map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('');label.hidden=!state.people.length}
function shrinkScheduleImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const scale=Math.min(1,1800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.86))};image.src=reader.result};reader.readAsDataURL(file)})}
function scheduleImportSummary(result){return result.schedules.map(schedule=>`<article><strong>${esc(schedule.name)}</strong><small>${schedule.weekdays.length?`Repeats: ${schedule.weekdays.map(day=>['','Mon','Tue','Wed','Thu','Fri'][day]).join(', ')}`:''}${schedule.dates.length?`${schedule.weekdays.length?' · ':''}${schedule.dates.length} dated day${schedule.dates.length===1?'':'s'}`:''}</small>${schedule.rows.map(row=>`<div><span>${esc(row.title)}</span><b>${esc(fmtTime(row.start))}–${esc(fmtTime(row.end))}</b></div>`).join('')}</article>`).join('')}
async function parseScheduleScreenshots(files){
  if(!state.people.length){toast('Add a child before importing a schedule');return}
  const accepted=[...files].filter(file=>/^image\/(png|jpeg|webp)$/i.test(file.type));if(!accepted.length)return;
  const button=document.querySelector('#attachScheduleImages'),result=document.querySelector('#scheduleImportResult'),list=document.querySelector('#scheduleImageList');button.disabled=true;button.querySelector('small').textContent='Reading schedule…';pendingScheduleImport=null;result.hidden=true;
  try{scheduleImportImages=await Promise.all(accepted.map(shrinkScheduleImage));list.hidden=false;list.innerHTML=scheduleImportImages.map((src,index)=>`<img src="${src}" alt="Schedule screenshot ${index+1}">`).join('');const owner=person(document.querySelector('#scheduleImportOwner').value),combined={studentName:owner.name,school:owner.school||'',notes:'',schedules:[]};for(let index=0;index<scheduleImportImages.length;index+=5){button.querySelector('small').textContent=`Reading ${index+1}–${Math.min(index+5,scheduleImportImages.length)} of ${scheduleImportImages.length}`;const response=await fetch(scheduleRelayUrl(),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({roomId:await syncRoomId(),studentName:owner.name,school:owner.school||'',images:scheduleImportImages.slice(index,index+5)})});const data=await response.json();if(!response.ok)throw Error(data.error||'Schedule import failed');combined.schedules.push(...(data.schedule.schedules||[]));if(data.schedule.notes)combined.notes+=(combined.notes?' ':'')+data.schedule.notes}pendingScheduleImport=combined;result.hidden=false;result.innerHTML=`<div class="import-review"><small>REVIEW BEFORE ADDING</small><h3>${esc(combined.studentName||owner.name)} · ${combined.schedules.length} schedule${combined.schedules.length===1?'':'s'}</h3>${combined.notes?`<p>${esc(combined.notes)}</p>`:''}${scheduleImportSummary(combined)}<div class="import-actions"><button type="button" data-cancel-schedule-import>Cancel</button><button type="button" class="primary" data-apply-schedule-import>Add to Daylight</button></div></div>`}catch(error){result.hidden=false;result.innerHTML=`<p class="import-error">${esc(error.message||'Schedule import failed.')}</p>`}finally{button.disabled=false;button.querySelector('small').textContent='Choose screenshots or photos for Daylight to read'}
}
function applyImportedSchedule(){const ownerId=document.querySelector('#scheduleImportOwner').value;if(!pendingScheduleImport||!ownerId)return;state.bellSchedules[ownerId]||={};state.specialBellSchedules[ownerId]||={};state.importedSchedules||=[];for(const schedule of pendingScheduleImport.schedules){const rows=schedule.rows.map(row=>[row.title,row.start,row.end]);for(const weekday of schedule.weekdays)state.bellSchedules[ownerId][weekday]=rows;for(const date of schedule.dates)state.specialBellSchedules[ownerId][date]={name:schedule.name,rows};state.importedSchedules.push({id:uid(),ownerId,name:schedule.name,weekdays:[...schedule.weekdays],dates:[...schedule.dates],rows,createdAt:new Date().toISOString()})}save();pendingScheduleImport=null;scheduleImportImages=[];document.querySelector('#scheduleImageList').hidden=true;document.querySelector('#scheduleImportResult').hidden=true;document.querySelector('#scheduleImageFiles').value='';renderAll();toast('Bell schedule added')}
document.querySelector('#attachScheduleImages').onclick=()=>{importOwnerOptions();if(!state.people.length){toast('Add a child first');return}document.querySelector('#scheduleImageFiles').click()};
document.querySelector('#scheduleImageFiles').onchange=e=>{importOwnerOptions();parseScheduleScreenshots(e.target.files)};
document.addEventListener('click',e=>{if(e.target.closest('[data-apply-schedule-import]'))applyImportedSchedule();if(e.target.closest('[data-cancel-schedule-import]')){pendingScheduleImport=null;scheduleImportImages=[];document.querySelector('#scheduleImageFiles').value='';document.querySelector('#scheduleImageList').hidden=true;document.querySelector('#scheduleImportResult').hidden=true}const remove=e.target.closest('[data-remove-imported-schedule]');if(remove){const item=(state.importedSchedules||[]).find(record=>record.id===remove.dataset.removeImportedSchedule);if(!item||!confirm(`Delete “${item.name}” from Daylight?`))return;for(const weekday of item.weekdays||[])if(JSON.stringify(state.bellSchedules?.[item.ownerId]?.[weekday])===JSON.stringify(item.rows))delete state.bellSchedules[item.ownerId][weekday];for(const date of item.dates||[])if(JSON.stringify(state.specialBellSchedules?.[item.ownerId]?.[date]?.rows)===JSON.stringify(item.rows))delete state.specialBellSchedules[item.ownerId][date];state.importedSchedules=state.importedSchedules.filter(record=>record.id!==item.id);save();openSheet('family');renderAll();toast('Imported schedule deleted')}});
document.querySelector('#onboarding')?.addEventListener('click',e=>{const choice=e.target.closest('[data-onboarding-choice]');if(choice){document.querySelector('#onboardingChoices').hidden=true;document.querySelector(`#${choice.dataset.onboardingChoice}FamilyForm`).hidden=false}if(e.target.closest('[data-onboarding-back]')){document.querySelectorAll('.onboarding-form').forEach(form=>form.hidden=true);document.querySelector('#onboardingChoices').hidden=false}});
document.querySelector('#createFamilyForm')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget),familyName=String(data.get('familyName')).trim(),memberName=String(data.get('memberName')).trim();state.profile={setupComplete:true,familyId:`family-${uid().slice(0,12)}`,familyName,memberId:`member-${uid().slice(0,10)}`,memberName,role:'owner',createdAt:new Date().toISOString()};state.preferences.familyName=familyName;state.preferences.weatherLocation=String(data.get('weatherLocation')||'').trim();state.syncSettings.pairingCode=crypto.randomUUID().replaceAll('-','').slice(0,12).toUpperCase();finishOnboarding()});
document.querySelector('#joinFamilyForm')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget),code=String(data.get('pairingCode')).trim().toUpperCase(),memberName=String(data.get('memberName')).trim();state.profile={setupComplete:true,familyId:`linked-${code}`,familyName:'Linked family',memberId:`member-${uid().slice(0,10)}`,memberName,role:'guardian',createdAt:new Date().toISOString()};state.syncSettings.pairingCode=code;finishOnboarding()});
ensureProfile();ensureIdentity();showOnboardingIfNeeded();renderAll();if(state.profile.setupComplete){connectSync();updateWeather();startLocationSharing()}setInterval(renderHeader,30000);setInterval(()=>{if(state.profile.setupComplete)updateWeather()},30*60*1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.profile.setupComplete){if(socket?.readyState!==WebSocket.OPEN)connectSync();startLocationSharing()}});window.addEventListener('online',()=>{if(state.profile.setupComplete&&socket?.readyState!==WebSocket.OPEN)connectSync()});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
